package org.eclipse.rdf4j.query.algebra.evaluation.impl.evaluationsteps;

/**
 * Execution-local coordinate trials. A selection changes only between completely drained input cohorts. Candidate
 * arrivals deliberately do not estimate predicate outcomes: downstream arrivals have already been filtered.
 */
final class AdaptiveFilterPlacementController {

	static final int CONTROL_COHORTS = 64;
	static final int TRIAL_COHORTS = 32;
	private static final int MAX_INTERVAL = 4096;

	@FunctionalInterface
	interface Candidates {
		/** Returns the next complete admitted placement, or -1 if this coordinate has no alternative. */
		int next(int filter, int selected);
	}

	/** Shared by regions of one evaluation, never by a prepared query or another evaluation. */
	static final class LearningBudget {
		private static final int MAX_TRIAL_COHORTS = 512;
		private int remaining = MAX_TRIAL_COHORTS;
		private AdaptiveFilterPlacementController owner;
		private boolean reservedTrialCohort;

		boolean acquire(AdaptiveFilterPlacementController controller) {
			if (remaining == 0 || owner != null) {
				return false;
			}
			owner = controller;
			// EXISTS/LIMIT can close a partial trial. Reserve that first observation at its start, since its work
			// consumes the query budget even when it never drains and provides no learning sample.
			remaining--;
			reservedTrialCohort = true;
			return true;
		}

		boolean trialCompleted() {
			if (reservedTrialCohort) {
				reservedTrialCohort = false;
			} else {
				remaining--;
			}
			return remaining > 0;
		}

		void release(AdaptiveFilterPlacementController controller) {
			if (owner == controller) {
				owner = null;
				reservedTrialCohort = false;
			}
		}
	}

	private enum Phase {
		BASELINE,
		TRIAL,
		CONTROL,
		COOLDOWN
	}

	private final LearningBudget budget;
	private final Candidates candidates;
	private final int[] selected;
	private final Window window = new Window();
	private Phase phase = Phase.BASELINE;
	private int coordinate;
	private int baselineSite;
	private int trialSite;
	private int interval = CONTROL_COHORTS;
	private int cooldown;
	private int completed;
	private long generation;
	private long commits;
	private long rejectedTrials;
	private long trials;
	private double beforeNanos;
	private double trialNanos;
	private boolean cohortOpen;
	private boolean closed;
	private boolean originalPlacement = true;

	AdaptiveFilterPlacementController(int[] candidateCounts, LearningBudget budget) {
		this(fixedCandidates(candidateCounts), candidateCounts.length, budget);
	}

	AdaptiveFilterPlacementController(Candidates candidates, int filters, LearningBudget budget) {
		this.candidates = candidates;
		this.budget = budget;
		selected = new int[filters];
	}

	private static Candidates fixedCandidates(int[] candidateCounts) {
		int[] counts = candidateCounts.clone();
		int[] next = new int[counts.length];
		return (filter, selected) -> {
			if (counts[filter] < 2) {
				return -1;
			}
			int candidate = ++next[filter] % counts[filter];
			return candidate == selected ? ++next[filter] % counts[filter] : candidate;
		};
	}

	void beginCohort() {
		if (closed || cohortOpen) {
			throw new IllegalStateException("Adaptive input cohort is already open or closed");
		}
		cohortOpen = true;
	}

	int selected(int filter) {
		return selected[filter];
	}

	boolean atOriginalPlacement() {
		return originalPlacement;
	}

	void completeCohort(long activeNanos) {
		if (!cohortOpen) {
			throw new IllegalStateException("Adaptive input cohort was not opened");
		}
		cohortOpen = false;
		completed++;
		if (phase == Phase.COOLDOWN) {
			if (--cooldown == 0) {
				phase = Phase.BASELINE;
			}
			return;
		}
		window.add(activeNanos);
		if (phase == Phase.BASELINE && window.count >= interval) {
			startTrial();
		} else if (phase == Phase.TRIAL) {
			boolean budgetAvailable = budget.trialCompleted();
			// A budget is checked at the drain boundary; an expensive in-flight cohort can overshoot it.
			if (window.count >= TRIAL_COHORTS || !budgetAvailable) {
				trialNanos = window.mean();
				change(baselineSite);
				phase = Phase.CONTROL;
				window.clear();
			}
		} else if (phase == Phase.CONTROL && window.count >= CONTROL_COHORTS) {
			finishTrial();
		}
	}

	private void startTrial() {
		if (!budget.acquire(this)) {
			window.clear();
			return;
		}
		int searched = 0;
		while (searched++ < selected.length) {
			int candidate = candidates.next(coordinate, selected[coordinate]);
			if (candidate >= 0) {
				baselineSite = selected[coordinate];
				trialSite = candidate;
				beforeNanos = window.mean();
				change(trialSite);
				phase = Phase.TRIAL;
				trials++;
				window.clear();
				return;
			}
			coordinate = (coordinate + 1) % selected.length;
		}
		budget.release(this);
		window.clear();
	}

	private void finishTrial() {
		// Real executions at the candidate must beat both surrounding control windows. No pass-rate transfer or
		// synthetic expression weights participate in the decision; all synchronous open/pull work is timed.
		if (trialNanos < beforeNanos && trialNanos < window.mean()) {
			change(trialSite);
			commits++;
		} else {
			rejectedTrials++;
		}
		budget.release(this);
		coordinate = (coordinate + 1) % selected.length;
		interval = Math.min(MAX_INTERVAL, interval * 2);
		cooldown = interval;
		phase = Phase.COOLDOWN;
		window.clear();
	}

	private void change(int site) {
		if (cohortOpen) {
			throw new IllegalStateException("Cannot change filter placement inside an input cohort");
		}
		if (selected[coordinate] != site) {
			selected[coordinate] = site;
			originalPlacement = true;
			for (int selectedSite : selected) {
				if (selectedSite != 0) {
					originalPlacement = false;
					break;
				}
			}
			generation++;
		}
	}

	void abort() {
		cohortOpen = false;
		closed = true;
		budget.release(this);
	}

	void close() {
		abort();
	}

	long generation() {
		return generation;
	}

	long commits() {
		return commits;
	}

	long trials() {
		return trials;
	}

	long rejectedTrials() {
		return rejectedTrials;
	}

	int completedCohorts() {
		return completed;
	}

	private static final class Window {
		private int count;
		private double total;

		void add(long nanos) {
			count++;
			total += Math.max(0L, nanos);
		}

		double mean() {
			return count == 0 ? 0 : total / count;
		}

		void clear() {
			count = 0;
			total = 0;
		}
	}
}
